import fs from 'node:fs';
import path from 'node:path';
import { exists, ensureDir, writeText, copyFile } from './fs.mjs';

function shellQuote(value) {
  return `'${String(value).replace(/'/g, `'\\''`)}'`;
}

function writeEnvFile(filePath, values) {
  const lines = [
    '# Generated by react-native-local-release interactive setup.',
    '# Never commit this file.',
    '',
    '# --- Apple App Store Connect API key ---',
    `ASC_KEY_ID=${values.ASC_KEY_ID}`,
    `ASC_ISSUER_ID=${values.ASC_ISSUER_ID}`,
    `ASC_KEY_FILEPATH=${values.ASC_KEY_FILEPATH}`,
    values.APPLE_ID ? `APPLE_ID=${values.APPLE_ID}` : '# APPLE_ID=',
    '',
    '# --- Google Play service account ---',
    `PLAY_JSON_KEY_PATH=${values.PLAY_JSON_KEY_PATH}`,
    '',
    '# --- Android upload keystore ---',
    `MYAPP_UPLOAD_STORE_FILE=${values.MYAPP_UPLOAD_STORE_FILE}`,
    `MYAPP_UPLOAD_KEY_ALIAS=${values.MYAPP_UPLOAD_KEY_ALIAS}`,
    `MYAPP_UPLOAD_STORE_PASSWORD=${values.MYAPP_UPLOAD_STORE_PASSWORD}`,
    `MYAPP_UPLOAD_KEY_PASSWORD=${values.MYAPP_UPLOAD_KEY_PASSWORD}`,
    '',
  ];
  writeText(filePath, lines.join('\n'));
}

function writeKeystoreProperties(filePath, values) {
  const lines = [
    '# Generated by react-native-local-release interactive setup.',
    '# Never commit this file.',
    '',
    `MYAPP_UPLOAD_STORE_FILE=${values.MYAPP_UPLOAD_STORE_FILE}`,
    `MYAPP_UPLOAD_KEY_ALIAS=${values.MYAPP_UPLOAD_KEY_ALIAS}`,
    `MYAPP_UPLOAD_STORE_PASSWORD=${values.MYAPP_UPLOAD_STORE_PASSWORD}`,
    `MYAPP_UPLOAD_KEY_PASSWORD=${values.MYAPP_UPLOAD_KEY_PASSWORD}`,
    '',
  ];
  writeText(filePath, lines.join('\n'));
}

function copyIntoSecrets(projectRoot, sourcePath, preferredName) {
  const secretsDir = path.join(projectRoot, 'secrets');
  ensureDir(secretsDir);
  const basename = preferredName || path.basename(sourcePath);
  const destRel = path.posix.join('secrets', basename);
  const destAbs = path.join(projectRoot, destRel);
  const absoluteSource = path.isAbsolute(sourcePath)
    ? sourcePath
    : path.resolve(projectRoot, sourcePath);
  if (!exists(absoluteSource)) {
    throw new Error(`Credential file not found: ${absoluteSource}`);
  }
  if (path.resolve(absoluteSource) !== path.resolve(destAbs)) {
    copyFile(absoluteSource, destAbs);
  }
  return destRel.replace(/\\/g, '/');
}

function copyKeystore(projectRoot, sourcePath) {
  const absoluteSource = path.isAbsolute(sourcePath)
    ? sourcePath
    : path.resolve(projectRoot, sourcePath);
  if (!exists(absoluteSource)) {
    throw new Error(`Keystore not found: ${absoluteSource}`);
  }
  const destRel = path.posix.join('android', 'app', path.basename(absoluteSource));
  const destAbs = path.join(projectRoot, destRel);
  if (path.resolve(absoluteSource) !== path.resolve(destAbs)) {
    ensureDir(path.dirname(destAbs));
    copyFile(absoluteSource, destAbs);
  }
  return path.basename(absoluteSource);
}

async function ask(rl, question, defaultValue = '') {
  const suffix = defaultValue ? ` [${defaultValue}]` : '';
  const answer = (await rl.question(`${question}${suffix}: `)).trim();
  return answer || defaultValue;
}

async function askYesNo(rl, question, defaultYes = false) {
  const hint = defaultYes ? 'Y/n' : 'y/N';
  const answer = (await rl.question(`${question} (${hint}): `)).trim().toLowerCase();
  if (!answer) {
    return defaultYes;
  }
  return answer === 'y' || answer === 'yes';
}

/**
 * Interactive credential onboarding. Writes gitignored files only.
 * Does not print secret values after they are entered.
 */
export async function setupCredentialsInteractively(rl, projectRoot, { dryRun = false } = {}) {
  console.log('');
  console.log('Credential setup');
  console.log('----------------');
  console.log('Values stay on this machine in gitignored files.');
  console.log('See docs/LOCAL_RELEASE.md or the package README for how to create these credentials.');
  console.log('');

  const wantApple = await askYesNo(rl, 'Configure Apple App Store Connect API credentials?', true);
  let apple = null;
  if (wantApple) {
    console.log('');
    console.log('Apple: App Store Connect → Users and Access → Integrations → App Store Connect API');
    const keyId = await ask(rl, 'ASC Key ID');
    const issuerId = await ask(rl, 'ASC Issuer ID');
    const keyPath = await ask(
      rl,
      'Path to AuthKey_XXXXXX.p8 (absolute or relative to project)',
    );
    const appleId = await ask(rl, 'Optional Apple ID email (press Enter to skip)', '');
    if (!keyId || !issuerId || !keyPath) {
      throw new Error('ASC_KEY_ID, ASC_ISSUER_ID, and .p8 path are required for Apple setup.');
    }
    apple = { keyId, issuerId, keyPath, appleId };
  }

  const wantPlay = await askYesNo(rl, 'Configure Google Play service-account credentials?', true);
  let play = null;
  if (wantPlay) {
    console.log('');
    console.log('Play: Google Cloud service account JSON + invite that email in Play Console');
    const jsonPath = await ask(
      rl,
      'Path to Play service-account JSON (absolute or relative to project)',
    );
    if (!jsonPath) {
      throw new Error('Play JSON path is required for Play setup.');
    }
    play = { jsonPath };
  }

  const wantAndroid = await askYesNo(rl, 'Configure Android upload keystore passwords?', true);
  let android = null;
  if (wantAndroid) {
    console.log('');
    console.log('Android: upload keystore used for Play signing (usually android/app/*.jks)');
    const storeFile = await ask(
      rl,
      'Path to upload keystore (.jks/.keystore)',
      'android/app/keystore.jks',
    );
    const alias = await ask(rl, 'Key alias', 'key0');
    console.log('(Passwords may be visible in this terminal; they are written only to gitignored files.)');
    const storePassword = await ask(rl, 'Keystore password');
    const keyPassword = await ask(rl, 'Key password', storePassword);
    if (!storeFile || !alias || !storePassword || !keyPassword) {
      throw new Error('Keystore path, alias, and passwords are required for Android setup.');
    }
    android = { storeFile, alias, storePassword, keyPassword };
  }

  if (!apple && !play && !android) {
    console.log('Skipped credential setup.');
    return { configured: false };
  }

  if (dryRun) {
    console.log('Dry run: would write fastlane/.env and/or android/keystore.properties');
    return { configured: true, dryRun: true };
  }

  ensureDir(path.join(projectRoot, 'secrets'));
  ensureDir(path.join(projectRoot, 'fastlane'));
  ensureDir(path.join(projectRoot, 'android'));

  const envValues = {
    ASC_KEY_ID: '',
    ASC_ISSUER_ID: '',
    ASC_KEY_FILEPATH: 'secrets/AuthKey_XXXXXXXXXX.p8',
    APPLE_ID: '',
    PLAY_JSON_KEY_PATH: 'secrets/play-store-service-account.json',
    MYAPP_UPLOAD_STORE_FILE: 'keystore.jks',
    MYAPP_UPLOAD_KEY_ALIAS: 'key0',
    MYAPP_UPLOAD_STORE_PASSWORD: '',
    MYAPP_UPLOAD_KEY_PASSWORD: '',
  };

  // Preserve existing env if present so partial setup does not wipe other values.
  const existingEnvPath = path.join(projectRoot, 'fastlane', '.env');
  if (exists(existingEnvPath)) {
    for (const line of fs.readFileSync(existingEnvPath, 'utf8').split('\n')) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#') || !trimmed.includes('=')) {
        continue;
      }
      const eq = trimmed.indexOf('=');
      const key = trimmed.slice(0, eq).trim();
      const value = trimmed.slice(eq + 1);
      if (key in envValues) {
        envValues[key] = value;
      }
    }
  }

  if (apple) {
    envValues.ASC_KEY_ID = apple.keyId;
    envValues.ASC_ISSUER_ID = apple.issuerId;
    envValues.ASC_KEY_FILEPATH = copyIntoSecrets(
      projectRoot,
      apple.keyPath,
      path.basename(apple.keyPath),
    );
    if (apple.appleId) {
      envValues.APPLE_ID = apple.appleId;
    }
  }

  if (play) {
    envValues.PLAY_JSON_KEY_PATH = copyIntoSecrets(
      projectRoot,
      play.jsonPath,
      path.basename(play.jsonPath),
    );
  }

  if (android) {
    envValues.MYAPP_UPLOAD_STORE_FILE = copyKeystore(projectRoot, android.storeFile);
    envValues.MYAPP_UPLOAD_KEY_ALIAS = android.alias;
    envValues.MYAPP_UPLOAD_STORE_PASSWORD = android.storePassword;
    envValues.MYAPP_UPLOAD_KEY_PASSWORD = android.keyPassword;
    writeKeystoreProperties(path.join(projectRoot, 'android', 'keystore.properties'), envValues);
  }

  writeEnvFile(existingEnvPath, envValues);

  console.log('');
  console.log('Credentials written to gitignored files:');
  console.log(`  - ${path.relative(projectRoot, existingEnvPath) || 'fastlane/.env'}`);
  if (android) {
    console.log('  - android/keystore.properties');
  }
  console.log('  - secrets/ (copied key files when needed)');
  console.log(`Tip: validate with: cd ${shellQuote(projectRoot)} && yarn release:credentials`);

  return { configured: true };
}

export { ask, askYesNo };
